<script setup lang="ts">
import { computed, ref, useId } from 'vue'
import AppIcon from './AppIcon.vue'
import ChoiceSelect from './ChoiceSelect.vue'
import { spectrumBrowser as state, runProcessing, cancelProcessing, setProcessingTarget, processingParameters } from '../lib/spectrumBrowser'
const page=ref(0),pageSize=12
const id=useId()
const result=computed(()=>state.processingResult)
const rows=computed(()=>result.value?.peaks.slice(page.value*pageSize,(page.value+1)*pageSize)??[])
// Curve targets span every loaded file; value is docKey:curveId and the first
// colon always splits it because document keys are uuid hex without colons.
const targetOptions=computed(()=>state.docs.flatMap(doc=>doc.spectrum.curves.map(c=>({value:doc.key+':'+c.id,label:doc.name+' · '+c.label}))))
const targetValue=computed(()=>state.target?state.target.docKey+':'+state.target.curve:'')
const resultDoc=computed(()=>state.docs.find(d=>d.key===result.value?.docKey))
const resultOrphan=computed(()=>!!result.value&&!!result.value.docKey&&!state.docs.some(d=>d.key===result.value!.docKey))
function canonical(value:Record<string,unknown>){const p={...value};if(Array.isArray(p.scales))p.scales=[...new Set(p.scales)].sort((a,b)=>Number(a)-Number(b));for(const key of p.mode==='background'?['wavelet','scales','neighbor','min_length','threshold','window']:p.mode==='peaks'?['order','epsilon','max_iter']:[])delete p[key];return JSON.stringify(Object.fromEntries(Object.entries(p).sort(([a],[b])=>a.localeCompare(b))))}
const stale=computed(()=>!!result.value&&canonical(processingParameters())!==canonical(result.value.parameters))
const modes=[{value:'background',label:'仅估计／扣除背景'},{value:'peaks',label:'仅小波寻峰（原始曲线）'},{value:'both',label:'先扣背景 → 小波寻峰'}]
const wavelets=['mexh','morl','gaus1','gaus2'].map(value=>({value,label:value}))
const views=computed(()=>[{value:'original',label:'原始测量曲线'},...(result.value?.background?[{value:'background',label:'估计背景'},{value:'corrected',label:'扣背景曲线'}]:[])])
async function run(){page.value=0;await runProcessing()}
</script>
<template>
  <section class="panel processing-panel"><button type="button" class="processing-heading" :aria-controls="id" :aria-expanded="state.processingExpanded" @click="state.processingExpanded=!state.processingExpanded"><h2>光谱预处理</h2><span v-if="state.processingPending">处理中…</span><span v-else-if="state.processingError" class="error-text">处理失败</span><span v-else-if="result">{{ result.peaks.length }} 峰</span><AppIcon name="chevron" :size="14" :class="{expanded:state.processingExpanded}" /></button><div :id="id" v-show="state.processingExpanded" class="processing-body">
    <template v-if="state.docs.length&&targetOptions.length"><ChoiceSelect :model-value="targetValue" label="处理原始曲线（文件 · 曲线）" :options="targetOptions" :disabled="state.processingPending||state.importing" @update:model-value="setProcessingTarget" /><ChoiceSelect v-model="state.processing.mode" label="处理步骤" :options="modes" :disabled="state.processingPending" />
      <details class="processing-parameters"><summary>详细参数</summary><fieldset class="control-fieldset" :disabled="state.processingPending"><template v-if="state.processing.mode!=='peaks'"><div class="row2"><label class="field">交替阶数<input v-model="state.processing.order" inputmode="numeric" /></label><label class="field">最大迭代<input v-model="state.processing.max_iter" inputmode="numeric" /></label></div><label class="field">面积相对变化阈值<input v-model="state.processing.epsilon" inputmode="decimal" /></label></template><template v-if="state.processing.mode!=='background'"><ChoiceSelect v-model="state.processing.wavelet" label="连续小波" :options="wavelets" /><label class="field">尺度（样本点，逗号分隔）<input v-model="state.processing.scales" /></label><div class="row2"><label class="field">脊线邻域<input v-model="state.processing.neighbor" inputmode="numeric" /></label><label class="field">最短脊线<input v-model="state.processing.min_length" inputmode="numeric" /></label></div><div class="row2"><label class="field">小波系数阈值<input v-model="state.processing.threshold" inputmode="decimal" /></label><label class="field">峰位修正窗口<input v-model="state.processing.window" inputmode="numeric" /></label></div></template></fieldset></details>
      <div class="processing-actions"><button type="button" class="btn primary" :disabled="state.processingPending||state.pending||!state.target" @click="run">运行处理</button><button v-if="state.processingPending" type="button" class="btn" @click="cancelProcessing">取消处理</button><button type="button" class="btn" @click="state.processingView='original'">恢复原始视图</button></div><p v-if="state.processingPending" class="hint" role="status">正在处理所选曲线…</p><p v-if="state.processingError" class="error-text" role="alert">{{ state.processingError }}</p><p v-if="!state.target" class="hint">先在上方选择要处理的文件与曲线。</p>
      <template v-if="result"><ChoiceSelect v-model="state.processingView" label="主图／概览显示" :options="views" /><p class="hint">{{ resultDoc?.name ?? '已移除文件' }} · {{ result.peaks.length }} 个峰 · 背景 {{ result.iterations }} 次迭代<span v-if="result.iteration_limit_reached">（已到上限，未收敛）</span><span v-else-if="result.iterations">（面积停止条件已满足，不代表逐点收敛）</span></p><p v-if="stale" class="hint">参数已编辑；当前显示上次运行结果，点击运行后更新。</p><p v-if="resultOrphan" class="hint">所属文件已移除；结果仅保留显示，重新选择曲线后更新。</p><details><summary>峰表与处理来源</summary><p class="hint">输入曲线 {{ result.curve }} · {{ result.source.unit }} · SHA256 {{ result.source.sha256.slice(0,12) }}…</p><div class="processing-table"><table><thead><tr><th>原节点</th><th>位置</th><th>处理输入强度</th><th>原始强度</th></tr></thead><tbody><tr v-for="(p,i) in rows" :key="i"><td>{{ p.index+1 }}</td><td>{{ p.x.toPrecision(7) }}</td><td>{{ p.intensity.toPrecision(7) }}</td><td>{{ p.original_intensity.toPrecision(7) }}</td></tr></tbody></table></div><p v-if="!result.peaks.length" class="hint">0 峰是有效结果；没有虚构峰位。</p><div class="pager"><span>{{ page+1 }}／{{ Math.max(1,Math.ceil(result.peaks.length/pageSize)) }}</span><div><button class="btn sm" :disabled="page===0" @click="page--">上一页</button><button class="btn sm" :disabled="(page+1)*pageSize>=result.peaks.length" @click="page++">下一页</button></div></div><pre>{{ JSON.stringify(result.parameters,null,2) }}</pre><p class="hint">{{ result.note }}</p></details></template>
    </template><p v-else class="hint">先导入文件并成功选择测量曲线，再估计背景或寻峰。</p>
  </div></section>
</template>
<style scoped>
.processing-panel{padding:0;min-width:0}.processing-heading{display:flex;width:100%;align-items:center;gap:10px;padding:17px 20px;border:0;background:transparent;border-radius:13px;color:var(--text);text-align:left}.processing-heading h2{margin:0;margin-right:auto}.processing-heading span{font-size:11px;color:var(--muted)}.processing-heading svg{transition:transform .18s}.processing-heading svg.expanded{transform:rotate(90deg)}.processing-body{padding:0 20px 18px}.processing-panel .hint{margin:10px 0}.processing-actions{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0}.processing-parameters{margin:12px 0}.processing-parameters .field{margin-top:10px}summary{cursor:pointer;color:var(--accent-text)}.processing-table{max-width:100%;overflow:auto}.processing-table table{font-size:11px}.processing-table th,.processing-table td{padding:8px;white-space:nowrap}.pager{flex-wrap:wrap}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:11px;color:var(--muted)}@media(max-width:740px){.processing-heading{padding:16px}.processing-body{padding:0 16px 16px}}
</style>
